require_once __DIR__.'/includes/auth.php'; if(currentUser())redirect(url('admin/dashboard.php')); if(setting('allow_registration','0')!=='1'){http_response_code(403);exit('التسجيل العام مغلق حاليًا.');}$errors=[];
if(isPost()){verifyCsrf();$name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');if(mb_strlen($name)<3)$errors[]='الاسم قصير جدًا.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='البريد الإلكتروني غير صالح.';if(strlen($pass)<8)$errors[]='كلمة المرور يجب ألا تقل عن 8 أحرف.';if($pass!==($_POST['confirm_password']??''))$errors[]='كلمتا المرور غير متطابقتين.';$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);if($s->fetch())$errors[]='البريد الإلكتروني مستخدم مسبقًا.';if(!$errors){$s=db()->prepare("INSERT INTO users(name,email,password,role,status,created_at,updated_at) VALUES(?,?,?,'author','active',NOW(),NOW())");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('success','تم إنشاء الحساب. يمكنك تسجيل الدخول.');redirect(url('login.php'));}}
$pageTitle='إنشاء حساب';require __DIR__.'/includes/header.php';?><div class="container auth-shell py-5"><div class="auth-card"><h1 class="h3 fw-bold mb-4 text-center">إنشاء حساب كاتب</h1><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><div class="mb-3"><label class="form-label">الاسم الكامل</label><input class="form-control" name="name" required value="<?=e($_POST['name']??'')?>"></div><div class="mb-3"><label class="form-label">البريد الإلكتروني</label><input class="form-control" type="email" name="email" required value="<?=e($_POST['email']??'')?>"></div><div class="mb-3"><label class="form-label">كلمة المرور</label><input class="form-control" type="password" name="password" required></div><div class="mb-4"><label class="form-label">تأكيد كلمة المرور</label><input class="form-control" type="password" name="confirm_password" required></div><button class="btn btn-primary w-100">إنشاء الحساب</button></form></div></div><?php require __DIR__.'/includes/footer.php';?>
